  ('d_stock_win', 'daily', 25, 60, '{}'::jsonb, 4, true, '산 주식이 갑자기 올랐다.', '{"stats": {"wealth": 8, "happy": 3}}'::jsonb, null, null, null),
  ('d_sick', 'daily', 35, 85, '{}'::jsonb, 5, false, '건강검진에서 경고를 받았다.', '{"stats": {"health": -6}, "add": ["sick"]}'::jsonb, null, null, null),
  ('d_lonely', 'daily', 30, 70, '{"max": {"charm": 40}}'::jsonb, 10, true, '주말 내내 아무와도 말하지 않았다.', '{"stats": {"happy": -4}, "add": ["lonely"]}'::jsonb, null, null, null),
  ('d_yang', 'daily', 20, 60, '{"job": ["vtuber"]}'::jsonb, 20, true, '고정 시청자들이 생겼다. 팬들을 ''양''이라고 부르기로 했다.', '{"stats": {"happy": 6}, "add": ["yangs"]}'::jsonb, null, '오늘 시청자가 열 명을 넘었다. 양들이 생겼다.', null),
  ('d_stream_song', 'daily', 20, 80, '{"job": ["vtuber"]}'::jsonb, 8, false, '노래 방송을 했다. 채팅창이 ''ㅋㅋㅋ''로 가득 찼다.', '{"stats": {"happy": 3, "charm": 2}}'::jsonb, null, null, null),
  ('d_shop_hit', 'daily', 28, 75, '{"job": ["gukbap", "chef", "cafe"]}'::jsonb, 10, true, '가게 앞에 줄이 생겼다.', '{"stats": {"wealth": 6, "happy": 3}}'::jsonb, null, null, null),
  ('d_grandkid', 'daily', 55, 90, '{"flags": ["kid"]}'::jsonb, 12, true, '손주가 태어났다.', '{"stats": {"happy": 6}}'::jsonb, null, null, null),
  ('d_walk', 'daily', 60, 100, '{}'::jsonb, 6, false, '매일 아침 동네 한 바퀴를 걸었다.', '{"stats": {"health": 2, "happy": 1}}'::jsonb, null, null, null),
  ('d_reunion', 'daily', 60, 90, '{"flags": ["friend"]}'::jsonb, 10, true, '어릴 적 친구와 다시 만나 밤새 웃었다.', '{"stats": {"happy": 6}}'::jsonb, null, null, null),
  ('d_memory', 'daily', 70, 100, '{}'::jsonb, 10, true, '오래된 일기장을 꺼내 읽었다.', '{"stats": {"happy": 3}}'::jsonb, null, '생각보다 괜찮은 인생이었다.', null),
  ('d_wolf1', 'daily', 12, 40, '{}'::jsonb, 2, true, '늑대 탈을 쓴 꿈을 꿨다. 이상하게 익숙했다.', '{"stats": {}, "add": ["wolf_dream1"]}'::jsonb, null, null, null),
  ('d_wolf2', 'daily', 15, 60, '{"flags": ["wolf_dream1"]}'::jsonb, 6, true, '또 늑대 꿈을 꿨다. 이번엔 누군가 ''양''이라고 불렀다.', '{"stats": {}, "add": ["wolf_dream2"]}'::jsonb, null, null, null),
  ('c_broadcast', 'crossroad', 15, 19, '{"min": {"talent": 40}}'::jsonb, 20, true, '유진이 방송을 해보고 싶다며 조심스럽게 말을 꺼낸다.', '{}'::jsonb, '[{"key": "A", "text": "장비를 사준다", "hint": "재산 ↓ 행복 ↑", "result": "보호자가 새 장비를 사줬다.", "effects": {"stats": {"wealth": -6, "happy": 5, "talent": 3}, "add": ["mic", "broadcast_start"]}}, {"key": "B", "text": "공부부터 하라고 한다", "hint": "지능 ↑ 행복 ↓", "result": "방송은 대학 가서 하기로 했다.", "effects": {"stats": {"intel": 4, "happy": -4}}}, {"key": "C", "text": "몰래 응원만 한다", "hint": "???", "result": "보호자가 몰래 응원해 줬다. 첫 방송을 켰다.", "effects": {"stats": {"happy": 3}, "add": ["broadcast_start", "secret_support"]}}]'::jsonb, null, null),
  ('c_music_school', 'crossroad', 14, 18, '{"flags": ["music"]}'::jsonb, 20, true, '예고 입시를 보고 싶다고 한다.', '{}'::jsonb, '[{"key": "A", "text": "보낸다", "hint": "끼 ↑ 재산 ↓", "result": "예고에 합격했다.", "effects": {"stats": {"talent": 8, "wealth": -6}, "add": ["music_school"]}}, {"key": "B", "text": "취미로만 하라고 한다", "hint": "지능 ↑ 행복 ↓", "result": "기타는 방 구석에 세워뒀다.", "effects": {"stats": {"intel": 3, "happy": -3}}}]'::jsonb, null, null),
  ('c_university', 'crossroad', 18, 19, '{}'::jsonb, 30, true, '수능이 끝났다. 진로를 정해야 한다.', '{}'::jsonb, '[{"key": "A", "text": "대학에 간다", "hint": "지능 ↑ 재산 ↓", "result": "대학에 입학했다.", "effects": {"stats": {"intel": 6, "wealth": -4}, "add": ["college"]}}, {"key": "B", "text": "바로 일을 시작한다", "hint": "재산 ↑", "result": "일찍 사회에 나가기로 했다.", "effects": {"stats": {"wealth": 5, "intel": -1}}}, {"key": "C", "text": "1년 쉬면서 하고 싶은 걸 찾는다", "hint": "행복 ↑ 끼 ↑", "result": "1년 동안 하고 싶은 걸 찾아다녔다.", "effects": {"stats": {"happy": 4, "talent": 3}, "add": ["dream_chase"]}}]'::jsonb, null, null),
  ('c_vtuber_debut', 'crossroad', 20, 35, '{"flags": ["broadcast_start"], "nojob": ["vtuber"]}'::jsonb, 25, true, '버추얼 데뷔 제안이 들어왔다.', '{}'::jsonb, '[{"key": "A", "text": "데뷔한다", "hint": "끼 ↑", "result": "늑대 귀가 달린 아바타로 데뷔했다.", "effects": {"stats": {"talent": 4, "happy": 3}, "add": ["vtuber_debut"], "job": "vtuber"}, "diary": "오늘부터 나는 버튜버다."}, {"key": "B", "text": "거절한다", "hint": "재산 ↑ 행복 ↓", "result": "방송은 추억으로 남기기로 했다.", "effects": {"stats": {"wealth": 2, "happy": -2}}}]'::jsonb, null, null),
  ('c_quit_job', 'crossroad', 25, 45, '{"job": ["office", "civil", "programmer", "delivery", "conv_store"]}'::jsonb, 15, true, '회사를 그만두고 하고 싶은 걸 하고 싶다고 한다.', '{}'::jsonb, '[{"key": "A", "text": "응원한다", "hint": "행복 ↑ 재산 ↓", "result": "사표를 냈다. 속이 시원했다.", "effects": {"stats": {"happy": 6, "wealth": -8}, "add": ["dream_chase"]}}, {"key": "B", "text": "현실을 생각하라고 한다", "hint": "재산 ↑ 행복 ↓", "result": "한숨을 쉬고 다시 출근했다.", "effects": {"stats": {"wealth": 4, "happy": -4}}}]'::jsonb, null, null),
  ('c_marry', 'crossroad', 26, 40, '{"flags": ["love"], "noflags": ["married"]}'::jsonb, 20, true, '연인이 결혼하자고 한다.', '{}'::jsonb, '[{"key": "A", "text": "한다", "hint": "행복 ↑ 재산 ↓", "result": "작은 결혼식을 올렸다.", "effects": {"stats": {"happy": 6, "wealth": -5}, "add": ["married"]}}, {"key": "B", "text": "아직은 이르다", "hint": "행복 ↓", "result": "결혼은 미루기로 했다. 연인은 떠났다.", "effects": {"stats": {"happy": -4}, "add": ["lonely"], "remove": ["love"]}}]'::jsonb, null, null),
  ('c_house', 'crossroad', 30, 50, '{"min": {"wealth": 35}}'::jsonb, 12, true, '집을 살까 고민 중이다.', '{}'::jsonb, '[{"key": "A", "text": "영끌한다", "hint": "재산 ↓ 행복 ↑", "result": "내 집이 생겼다. 대출도 생겼다.", "effects": {"stats": {"wealth": -15, "happy": 4}, "add": ["home_owner"]}}, {"key": "B", "text": "전세로 버틴다", "hint": "변화 없음", "result": "조금 더 지켜보기로 했다.", "effects": {}}]'::jsonb, null, null),
  ('c_shop', 'crossroad', 28, 55, '{"flags": ["cook"], "noflags": ["shop_owner"]}'::jsonb, 18, true, '가게를 차려보고 싶다고 한다.', '{}'::jsonb, '[{"key": "A", "text": "차린다", "hint": "재산 ↓", "result": "작은 가게를 열었다.", "effects": {"stats": {"wealth": -10, "happy": 3}, "add": ["shop_owner"]}}, {"key": "B", "text": "말린다", "hint": "행복 ↓", "result": "가게는 꿈으로 남겨두기로 했다.", "effects": {"stats": {"happy": -3}}}]'::jsonb, null, null),
  ('c_health', 'crossroad', 40, 75, '{"flags": ["sick"]}'::jsonb, 20, true, '의사가 생활 습관을 바꾸라고 한다.', '{}'::jsonb, '[{"key": "A", "text": "술·담배를 끊는다", "hint": "건강 ↑ 행복 ↓", "result": "독하게 마음먹고 끊었다.", "effects": {"stats": {"health": 10, "happy": -2}, "remove": ["sick"]}}, {"key": "B", "text": "하던 대로 산다", "hint": "건강 ↓ 행복 ↑", "result": "인생 뭐 있나 싶었다.", "effects": {"stats": {"happy": 2, "health": -6}}}]'::jsonb, null, null),
  ('c_fan_letter', 'crossroad', 22, 70, '{"job": ["vtuber"]}'::jsonb, 15, true, '시청자에게 긴 편지를 받았다.', '{}'::jsonb, '[{"key": "A", "text": "방송에서 읽어준다", "hint": "매력 ↑", "result": "방송에서 편지를 읽다가 목이 메었다.", "effects": {"stats": {"charm": 4, "happy": 4}, "add": ["yangs"]}}, {"key": "B", "text": "혼자 몰래 읽는다", "hint": "행복 ↑", "result": "편지를 지갑에 넣고 다녔다.", "effects": {"stats": {"happy": 5}}}]'::jsonb, null, null),
  ('c_retire', 'crossroad', 62, 75, '{}'::jsonb, 15, true, '은퇴 후 뭘 할지 고민 중이다.', '{}'::jsonb, '[{"key": "A", "text": "노래 교실에 다닌다", "hint": "행복 ↑ 끼 ↑", "result": "노래 교실에 등록했다. 선생님이 한숨을 쉬었다.", "effects": {"stats": {"happy": 5, "talent": 2}}}, {"key": "B", "text": "세계 일주를 떠난다", "hint": "재산 ↓ 행복 ↑", "result": "배낭 하나 메고 떠났다.", "effects": {"stats": {"wealth": -10, "happy": 8}, "add": ["travel"]}}, {"key": "C", "text": "집에서 푹 쉰다", "hint": "건강 ↑", "result": "드디어 늦잠을 잤다.", "effects": {"stats": {"health": 4, "happy": 2}}}]'::jsonb, null, null),
  ('c_wolf', 'crossroad', 16, 70, '{"flags": ["wolf_dream2"]}'::jsonb, 40, true, '꿈속 늑대가 ''이제 기억났냐''고 묻는다.', '{}'::jsonb, '[{"key": "A", "text": "기억났다고 대답한다", "hint": "???", "result": "늑대가 웃었다. 무언가 깨어난 기분이다.", "effects": {"stats": {"talent": 5}, "add": ["wolf_dream3"]}, "diary": "나는 원래 늑대였던 것 같다."}, {"key": "B", "text": "그냥 꿈이라고 넘긴다", "hint": "평범하게", "result": "그 뒤로 늑대 꿈은 꾸지 않았다.", "effects": {"stats": {"happy": 1}, "remove": ["wolf_dream1", "wolf_dream2"]}}]'::jsonb, null, null),
  ('r_lottery', 'rare', 20, 85, '{}'::jsonb, 10, true, '복권 2등에 당첨됐다!', '{"stats": {"wealth": 30, "happy": 8}}'::jsonb, null, null, '아주 가끔 하늘에서 돈이 떨어지면…'),
  ('r_ufo', 'rare', 10, 85, '{}'::jsonb, 10, true, '밤하늘에서 이상한 빛을 봤다. 아무도 믿어주지 않았다.', '{"stats": {"happy": 2}}'::jsonb, null, null, '밤하늘을 올려다보면…'),
  ('r_viral', 'rare', 18, 60, '{"anyflags": ["mic", "music", "artsy"]}'::jsonb, 10, true, '올린 영상이 하룻밤 사이에 백만 조회수를 찍었다.', '{"stats": {"charm": 10, "wealth": 8}, "add": ["fame"]}'::jsonb, null, null, '끼를 세상에 보여주면…'),
  ('r_celeb', 'rare', 15, 70, '{}'::jsonb, 10, true, '길에서 유명 연예인과 부딪혔다. 사인은 못 받았다.', '{"stats": {"happy": 3}}'::jsonb, null, null, '번화가를 걷다 보면…'),
  ('r_twin', 'rare', 15, 80, '{}'::jsonb, 10, true, '자신과 똑같이 생긴 사람을 봤다. 다른 평행세계의 유진일까?', '{"stats": {"happy": 1}}'::jsonb, null, null, '평행세계가 겹치는 순간이 있다면…'),
  ('r_hero', 'rare', 20, 70, '{}'::jsonb, 10, true, '물에 빠진 아이를 구했다. 뉴스에 나왔다.', '{"stats": {"charm": 8, "happy": 5}}'::jsonb, null, null, '용기를 내야 하는 순간이 오면…'),
  ('r_ghost', 'rare', 10, 70, '{}'::jsonb, 10, true, '새벽 3시, 방 안에서 누군가 이름을 불렀다.', '{"stats": {"happy": -3, "health": -1}}'::jsonb, null, null, '미스테리한 밤이 찾아오면…'),
  ('r_wolf_moon', 'rare', 16, 90, '{"flags": ["wolf_dream3"]}'::jsonb, 10, true, '보름달 아래서 늑대 울음소리를 따라 불렀다. 처음으로 음정이 맞았다.', '{"stats": {"talent": 10}}'::jsonb, null, null, '늑대의 기억을 되찾으면…')
insert into public.life_special_endings (id, title, text, cond, priority, hint) values
  ('wolf', '아무도 몰랐던 늑대 유진', '평생 사람인 척 살았지만, 마지막 보름달 아래서 유진은 원래 모습으로 돌아갔어요.', '{"flags": ["wolf_dream3"]}'::jsonb, 100, '늑대 꿈을 끝까지 따라가면…'),
  ('true_vtuber', '진짜 버튜버가 된 유진', '양들과 함께한 방송이 평생의 자랑이 됐어요.', '{"job": ["vtuber"], "flags": ["yangs"], "min": {"happy": 60}}'::jsonb, 80, '방송을 놓지 않고, 팬들에게 이름을 붙여주면…'),
  ('prodigal', '재벌가의 탕아 유진', '모든 걸 가지고 태어났지만, 모든 걸 잃고 떠났어요.', '{"house": ["rich"], "max": {"wealth": 15}}'::jsonb, 70, '모든 걸 가지고 태어나 모든 걸 잃으면…'),
  ('rags_riches', '단칸방에서 빌딩까지 올라간 유진', '단칸방 창문으로 보던 빌딩이 결국 유진의 것이 됐어요.', '{"house": ["poor"], "min": {"wealth": 90}}'::jsonb, 70, '가장 낮은 곳에서 가장 높은 곳으로 가면…')
